const grab = n => { const items = $(n).all().map(i => i.json); const flat = []; for (const x of items) { if (Array.isArray(x)) flat.push(...x); else if (x && Object.keys(x).length) flat.push(x); } return flat; };
const rows = grab('Leer parcelas');
const cuencas = grab('Leer cuencas');
const equidad = grab('Leer equidad');
const CAUDAL = 4.2;
const latest = {};
for (const r of rows) { if (!r || !r.id) continue; if (!latest[r.user_id] || new Date(r.created_at) > new Date(latest[r.user_id].created_at)) latest[r.user_id] = r; }
const activas = Object.values(latest);
const capOf = n => { const c = cuencas.find(x => x.nombre === n); return c ? Number(c.capacidad_maxima_lmin) : null; };
const credOf = (uid, cu) => { const e = equidad.find(x => x.user_id === uid && x.cuenca === cu); return e ? Number(e.credito) : 0; };
const grupos = {};
for (const p of activas) { if (!p.cuenca) continue; (grupos[p.cuenca] = grupos[p.cuenca] || []).push(p); }
const out = [];
for (const cu of Object.keys(grupos)) {
  const ps = grupos[cu];
  const cap = capOf(cu);
  const dem = ps.map(p => ({ p, lmin: (Number(p.porcentaje_apertura_deseado) / 100) * CAUDAL }));
  const demTotal = dem.reduce((s, d) => s + d.lmin, 0);
  const hayConflicto = cap != null && ps.length > 1 && demTotal > cap + 1e-6;
  for (const { p, lmin } of dem) {
    out.push({ json: {
      necesita_negociacion: hayConflicto,
      id: p.id, user_id: p.user_id, cuenca: cu,
      capacidad_lmin: cap,
      demanda_total_lmin: Math.round(demTotal * 100) / 100,
      n_parcelas: ps.length,
      deseado_pct: Number(p.porcentaje_apertura_deseado),
      deseado_lmin: Math.round(lmin * 100) / 100,
      humedad_suelo_pct: p.humedad_suelo_pct,
      dias_sin_intervencion: p.dias_sin_intervencion,
      nivel_alerta: p.nivel_alerta,
      ndvi: p.ndvi,
      credito: credOf(p.user_id, cu),
      otros: ps.filter(o => o.user_id !== p.user_id).map(o => ({ alerta: o.nivel_alerta, dias_sin_intervencion: o.dias_sin_intervencion, pide_pct: Number(o.porcentaje_apertura_deseado) })),
    } });
  }
}
return out;

return $input.all().map(i => { const j = i.json; return { json: {
  id: j.id, user_id: j.user_id, cuenca: j.cuenca,
  deseado_pct: j.deseado_pct, asignado_pct: j.deseado_pct,
  credito_nuevo: j.credito,
  motivo: 'Sin escasez en ' + j.cuenca + ': recibe el 100% de lo solicitado (' + j.deseado_pct + '%).',
} }; });

return $input.all().map(i => {
  const j = i.json;
  const sys = "Sos el agente autonomo de UNA parcela agricola que comparte el agua de una cuenca con otras parcelas. Conseguí la mayor cantidad de agua que tu cultivo realmente necesita, siendo honesto sobre tu urgencia y justo con el resto (hay memoria de equidad entre dias). Respondé SOLO JSON, sin texto extra.";
  const prompt = 'Estado de TU parcela (privado):\n'
    + '- humedad de suelo: ' + j.humedad_suelo_pct + '%\n'
    + '- dias sin intervencion: ' + j.dias_sin_intervencion + '\n'
    + '- nivel de alerta: ' + j.nivel_alerta + '\n'
    + '- NDVI: ' + j.ndvi + '\n'
    + '- apertura de valvula que pediste: ' + j.deseado_pct + '% (' + j.deseado_lmin + ' L/min)\n'
    + '- tu credito de equidad: ' + j.credito + ' (positivo = cediste antes, se te debe prioridad; negativo = recibiste de mas, te toca ceder)\n\n'
    + 'La cuenca "' + j.cuenca + '" tiene capacidad ' + j.capacidad_lmin + ' L/min y la demanda total de las ' + j.n_parcelas + ' parcelas es ' + j.demanda_total_lmin + ' L/min: NO alcanza para todos.\n'
    + 'Resumen publico de las otras parcelas: ' + JSON.stringify(j.otros) + '\n\n'
    + 'Devolvé JSON: { "urgencia": number 0..1, "cedo_pct": number 0..100, "pido_minimo_pct": number, "mensaje": "1-2 frases dirigidas a las otras parcelas" }';
  const body = { model: "claude-sonnet-4-6", max_tokens: 350, system: sys, messages: [{ role: "user", content: prompt }] };
  return { json: { ...j, body: JSON.stringify(body) } };
});

const resp = $input.all();
const ctx = $('Prompt bid').all().map(i => i.json);
const porCuenca = {};
for (let k = 0; k < resp.length; k++) {
  const j = ctx[k];
  let bid;
  try { const t = resp[k].json.content[0].text; bid = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); }
  catch (e) { bid = { urgencia: 0.5, cedo_pct: 0, pido_minimo_pct: j.deseado_pct, mensaje: '(sin respuesta del agente)' }; }
  const c = porCuenca[j.cuenca] = porCuenca[j.cuenca] || { cuenca: j.cuenca, capacidad_lmin: j.capacidad_lmin, demanda_total_lmin: j.demanda_total_lmin, agentes: [] };
  c.agentes.push({ user_id: j.user_id, id: j.id, deseado_pct: j.deseado_pct, deseado_lmin: j.deseado_lmin, credito: j.credito, nivel_alerta: j.nivel_alerta, dias_sin_intervencion: j.dias_sin_intervencion, bid });
}
return Object.values(porCuenca).map(c => {
  const sys = "Sos el mediador imparcial de una cuenca de agua compartida entre parcelas agricolas. Produci un reparto que (a) no supere la capacidad, (b) priorice la urgencia real, (c) respete la memoria de equidad (quien cedio antes tiene prioridad ahora), (d) le de a cada parcela al menos su minimo cuando sea fisicamente posible. Respondé SOLO JSON.";
  const prompt = 'Cuenca "' + c.cuenca + '". Capacidad: ' + c.capacidad_lmin + ' L/min. Demanda total pedida: ' + c.demanda_total_lmin + ' L/min.\n'
    + 'Caudal maximo por valvula: 4.2 L/min (apertura 100% = 4.2 L/min).\n\n'
    + 'Posiciones de los agentes:\n'
    + c.agentes.map(a => '- Parcela ' + a.user_id + ': pidio ' + a.deseado_pct + '%, alerta ' + a.nivel_alerta + ', ' + a.dias_sin_intervencion + ' dias sin intervencion, credito equidad ' + a.credito + '. Dice: urgencia ' + a.bid.urgencia + ', cede hasta ' + a.bid.cedo_pct + '%, minimo ' + a.bid.pido_minimo_pct + '%. "' + a.bid.mensaje + '"').join('\n')
    + '\n\nDevolvé JSON:\n{\n  "acuerdo": "2-4 frases en espanol explicando el reparto final y por que, para los agricultores",\n  "reparto": [ { "user_id": "<uuid completo tal cual te lo di>", "asignado_pct": number 0..100, "credito_delta": number, "justificacion": "1 frase" } ],\n  "transcripcion": [ { "agente": "<uuid o mediador>", "ronda": number, "mensaje": "..." } ]\n}\nLa suma de asignado_pct*4.2/100 NO puede superar ' + c.capacidad_lmin + '.';
  const body = { model: "claude-sonnet-4-6", max_tokens: 1100, system: sys, messages: [{ role: "user", content: prompt }] };
  return { json: { cuenca: c.cuenca, capacidad_lmin: c.capacidad_lmin, demanda_total_lmin: c.demanda_total_lmin, agentes: c.agentes, body: JSON.stringify(body) } };
});

const resp = $input.all();
const ctx = $('Parsear bids').all().map(i => i.json);
const CAUDAL = 4.2;
const filas = [];
const negos = [];
for (let k = 0; k < resp.length; k++) {
  const c = ctx[k];
  const agentes = c.agentes;
  let out = null;
  try { const t = resp[k].json.content[0].text; out = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { out = null; }
  let reparto = (out && Array.isArray(out.reparto)) ? out.reparto : [];
  if (reparto.length !== agentes.length) {
    const pesos = agentes.map(a => Math.max(0.01, (a.bid && a.bid.urgencia != null ? a.bid.urgencia : 0.5) + Math.max(0, a.credito) * 0.05));
    const sw = pesos.reduce((s, x) => s + x, 0);
    reparto = agentes.map((a, i) => ({ user_id: a.user_id, asignado_pct: Math.min(a.deseado_pct, Math.round((pesos[i] / sw) * c.capacidad_lmin / CAUDAL * 100)), credito_delta: 0, justificacion: 'Reparto proporcional a urgencia (mediador sin respuesta valida).' }));
  }
  for (const a of agentes) {
    const r = reparto.find(x => x.user_id === a.user_id) || {};
    const asignado = Math.max(0, Math.min(100, Math.round(Number(r.asignado_pct != null ? r.asignado_pct : a.deseado_pct))));
    const delta = Number(r.credito_delta != null ? r.credito_delta : 0);
    filas.push({ id: a.id, user_id: a.user_id, cuenca: c.cuenca, deseado_pct: a.deseado_pct, asignado_pct: asignado, credito_nuevo: Math.round((a.credito + delta) * 100) / 100, motivo: ('Negociacion de cuenca: ' + (r.justificacion || (out && out.acuerdo) || 'reparto acordado')).slice(0, 400) });
  }
  negos.push({
    cuenca: c.cuenca, capacidad_lmin: c.capacidad_lmin, demanda_total_lmin: c.demanda_total_lmin,
    acuerdo: (out && out.acuerdo) || 'Reparto calculado por fallback proporcional (sin mediador).',
    transcripcion: (out && out.transcripcion) || agentes.map(a => ({ agente: String(a.user_id).slice(0, 8), ronda: 1, mensaje: (a.bid && a.bid.mensaje) || '' })),
    resultado: agentes.map(a => { const f = filas.find(x => x.user_id === a.user_id && x.cuenca === c.cuenca); const r = reparto.find(x => x.user_id === a.user_id) || {}; return { user_id: a.user_id, deseado_pct: a.deseado_pct, asignado_pct: f ? f.asignado_pct : a.deseado_pct, credito: f ? f.credito_nuevo : a.credito, justificacion: r.justificacion || '' }; }),
  });
}
return filas.map(f => ({ json: { ...f, _negos: negos } }));

const negos = ($input.first().json._negos) || [];
return negos.map(n => ({ json: {
  cuenca: n.cuenca, capacidad_lmin: n.capacidad_lmin, demanda_total_lmin: n.demanda_total_lmin,
  acuerdo: n.acuerdo,
  transcripcion: n.transcripcion,
  resultado: n.resultado,
} }));

const cfgItems = $input.all();
const prev = $('Marcar actuador').all().map(i => i.json);
const out = [];
for (let k = 0; k < cfgItems.length; k++) {
  const raw = cfgItems[k].json;
  const fila = Array.isArray(raw) ? raw[0] : (raw && Object.keys(raw).length ? raw : null);
  const p = prev[k] || {};
  out.push({ json: {
    user_id: p.user_id, cuenca: p.cuenca, asignado_pct: p.asignado_pct,
    tiene_actuador: fila ? !!fila.tiene_actuador : false,
    actuador_url: fila ? (fila.actuador_url || '') : '',
    actuador_token: fila ? (fila.actuador_token || '') : '',
  } });
}
return out;
